+  if (task.due !== undefined && (typeof task.due !== "string" || !isDate(task.due))) return false;
+  if (task.completedAt !== undefined && !isIso(task.completedAt)) return false;
+  return (task.status === "done") === (task.completedAt !== undefined);
+}
+
+async function load(): Promise<Database> {
+  const path = Bun.file(file);
+  if (!(await path.exists())) return { nextId: 1, tasks: [] };
+  let parsed: unknown;
+  try {
