+  } catch {
+    fail(`Malformed taskboard database: ${file}`);
+  }
+  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) fail(`Malformed taskboard database: ${file}`);
+  const db = parsed as Record<string, unknown>;
+  if (!Number.isSafeInteger(db.nextId) || (db.nextId as number) < 1 || !Array.isArray(db.tasks) || !db.tasks.every(validTask)) {
+    fail(`Malformed taskboard database: ${file}`);
+  }
